<!-- wp:paragraph {"align":"center","style":{"color":{"text":"#383544"},"typography":{"fontSize":"16px","lineHeight":"2"},"spacing":{"margin":{"top":"28px","bottom":"24px"}}}} -->
<p class="has-text-align-center has-text-color" style="color:#383544;font-size:16px;line-height:2;margin-top:28px;margin-bottom:24px">たくさんの条件があるように見えますが、実際に結論を分けるのはこの3つです。</p>
<!-- /wp:paragraph -->
<!-- wp:wdl/lw-pr-column-1 {"columnsPc":3,"columnWidthsPc":[1,1,1],"columnsSp":1,"columnGapPc":16,"wrapPaddingTopPc":0,"wrapPaddingBottomPc":0,"itemBgNone":false,"itemBgTypePc":"solid","itemBgColorPc":"#ffffff","itemBgTypeSp":"solid","itemBgColorSp":"#ffffff","itemBorderColorPc":"#ddd8e8","itemBorderWidthPc":1,"itemBorderStylePc":"solid","itemBorderColorSp":"#ddd8e8","itemBorderWidthSp":1,"itemBorderStyleSp":"solid","itemPaddingTopPc":28,"itemPaddingBottomPc":28,"itemPaddingLeftPc":24,"itemPaddingRightPc":24,"itemPaddingTopSp":20,"itemPaddingBottomSp":20,"itemPaddingLeftSp":18,"itemPaddingRightSp":18,"itemBorderRadiusTopLeftPc":8,"itemBorderRadiusTopRightPc":8,"itemBorderRadiusBottomRightPc":8,"itemBorderRadiusBottomLeftPc":8,"itemBorderRadiusTopLeftSp":8,"itemBorderRadiusTopRightSp":8,"itemBorderRadiusBottomRightSp":8,"itemBorderRadiusBottomLeftSp":8} -->
<div class="wp-block-wdl-lw-pr-column-1 lw-pr-column-1" style="--column-1-wrap-padding-pc:0px 0px 0px 0px;--column-1-wrap-padding-sp:0px 0px 0px 0px;--column-1-border-color-pc:rgb(131, 131, 131);--column-1-border-width-pc:0px;--column-1-border-style-pc:solid;--column-1-border-color-sp:rgb(131, 131, 131);--column-1-border-width-sp:0px;--column-1-border-style-sp:solid;--column-1-bdr-pc:0px 0px 0px 0px;--column-1-bdr-sp:0px 0px 0px 0px;--column-1-gtc-pc:1fr 1fr 1fr;--column-1-gtc-sp:1fr;--column-1-row-gap-pc:8px;--column-1-row-gap-sp:8px;--column-1-column-gap-pc:16px;--column-1-column-gap-sp:16px;--column-1-item-bg-pc:#ffffff;--column-1-item-bg-sp:#ffffff;--column-1-item-min-h-pc:0px;--column-1-item-min-h-sp:0px;--column-1-item-padding-pc:28px 24px 28px 24px;--column-1-item-padding-sp:20px 18px 20px 18px;--column-1-item-bdr-pc:8px 8px 8px 8px;--column-1-item-bdr-sp:8px 8px 8px 8px;--column-1-item-border-color-pc:#ddd8e8;--column-1-item-border-width-pc:1px;--column-1-item-border-style-pc:solid;--column-1-item-border-color-sp:#ddd8e8;--column-1-item-border-width-sp:1px;--column-1-item-border-style-sp:solid"><div class="custom_wrap"><!-- wp:wdl/lw-pr-column-1-item -->
<div class="wp-block-wdl-lw-pr-column-1-item custom_column_item"><!-- wp:heading {"level":3,"style":{"color":{"text":"#4b3b70"},"typography":{"fontSize":"18px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"16px"}}},"textAlign":"left"} -->
<h3 class="has-text-align-left has-text-color" style="color:#4b3b70;font-size:18px;line-height:1.6;margin-top:0px;margin-bottom:16px">① いつまでに現金が要るか</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#383544"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#383544;font-size:16px;line-height:1.9">半年以内に現金が必要なら、迷わず売却です。貸す場合、最初の入居者が決まるまで平均2〜4か月かかります。</p>
<!-- /wp:paragraph --></div>
<!-- /wp:wdl/lw-pr-column-1-item -->
<!-- wp:wdl/lw-pr-column-1-item -->
<div class="wp-block-wdl-lw-pr-column-1-item custom_column_item"><!-- wp:heading {"level":3,"style":{"color":{"text":"#4b3b70"},"typography":{"fontSize":"18px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"16px"}}},"textAlign":"left"} -->
<h3 class="has-text-align-left has-text-color" style="color:#4b3b70;font-size:18px;line-height:1.6;margin-top:0px;margin-bottom:16px">② 戻って住む可能性があるか</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#383544"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#383544;font-size:16px;line-height:1.9">少しでもあるなら賃貸です。売ってしまうと戻れません。転勤なら定期借家という形もあります。</p>
<!-- /wp:paragraph --></div>
<!-- /wp:wdl/lw-pr-column-1-item -->
<!-- wp:wdl/lw-pr-column-1-item -->
<div class="wp-block-wdl-lw-pr-column-1-item custom_column_item"><!-- wp:heading {"level":3,"style":{"color":{"text":"#4b3b70"},"typography":{"fontSize":"18px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"16px"}}},"textAlign":"left"} -->
<h3 class="has-text-align-left has-text-color" style="color:#4b3b70;font-size:18px;line-height:1.6;margin-top:0px;margin-bottom:16px">③ 修繕にいくら出せるか</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#383544"},"typography":{"fontSize":"16px","lineHeight":"1.9"}}} -->
<p class="has-text-color" style="color:#383544;font-size:16px;line-height:1.9">貸すには最低限の直しが要ります。給湯器・水回り・クロスで50〜150万円が目安です。</p>
<!-- /wp:paragraph --></div>
<!-- /wp:wdl/lw-pr-column-1-item --></div></div>
<!-- /wp:wdl/lw-pr-column-1 -->
