<!-- /wp:wdl/lw-space-1 -->
<!-- wp:wdl/custom-title-6 {"mainTitle":"あなたはどちらに当てはまりますか","accentColor":"#4b3b70","headingLevel":2} -->
<h2 class="wp-block-wdl-custom-title-6 custom-title-6"><div class="main"><span>あなたはどちらに当てはまりますか</span><div class="accent" style="background-color:#4b3b70"></div></div></h2>
